    },
    {
      "label": "(b)",
      "part_stem": "The radius of a small sphere is determined from a measurement of the volume of the sphere. The sphere is submerged in water, displacing some of the water into a measuring cylinder as shown in Fig. 1.1. Fig. 1.1 (not to scale) shows a sphere submerged in water with displaced water collected in a measuring cylinder. The measured volume of displaced water is $(28.0 \\pm 0.5)\\,\\mathrm{cm^3}$. Calculate:",
      "text": null,
      "marks": 0,
      "answer_prompt": null,
      "unit": null
    },
    {
      "label": "(b)(i)",
      "part_stem": null,
      "text": "the radius, in cm, of the sphere",
      "marks": 1,
      "answer_prompt": null,
      "unit": null
    },
    {
      "label": "(b)(ii)",
      "part_stem": null,
      "text": "the percentage uncertainty in the radius of the sphere.",
      "marks": 2,
      "answer_prompt": null,
      "unit": null
    }
  ],
  "markscheme": [
    {
      "label": "(a)",
      "marks": 2,
      "marking_points": [
        {
          "tag": "B1",
          "text": "scalar and vector have magnitude"
        },
        {
          "tag": "B1",
          "text": "vector has direction (and scalar does not have direction)"
        }
      ]
    },
    {
      "label": "(b)(i)",
      "marks": 1,
      "marking_points": [
        {
          "tag": "A1",
          "text": "$r = [(3 \\times 28) / 4\\pi]^{1/3}$ $= 1.9\\,\\mathrm{cm}$"
        }
      ]
    },
    {
      "label": "(b)(ii)",
      "marks": 2,
      "marking_points": [
        {
          "tag": "C1",
          "text": "percentage uncertainty in $V = (0.5 / 28) \\times 100$ $(= 1.79\\%)$"
        },
        {
          "tag": "A1",
          "text": "percentage uncertainty in $r = 1.79 / 3$ $= 0.6\\%$"
        }
      ]
    }
  ]
}
